create type public.nonconformity_type as enum ('NONCONFORMITY','OBSERVATION','IMPROVEMENT_OPPORTUNITY'); create type public.nonconformity_status as enum ('OPEN','CORRECTION','CORRECTIVE_ACTION','EFFECTIVENESS','CLOSED');
create sequence public.nonconformity_number_sequence start 1; create or replace function public.next_nonconformity_number() returns text language plpgsql volatile set search_path=public as $$ begin return format('NC-%s-%s',to_char(current_date,'YYYY'),lpad(nextval('public.nonconformity_number_sequence')::text,6,'0')); end; $$;
create table public.nonconformities(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete restrict,nonconformity_number text not null unique default public.next_nonconformity_number(),record_type public.nonconformity_type not null,status public.nonconformity_status not null default 'OPEN',requirement_reference text,description text not null check(length(trim(description)) between 10 and 10000),immediate_correction text,root_cause text,owner_id uuid references public.user_profiles(id) on delete set null,due_at timestamptz,created_by uuid not null references public.user_profiles(id) on delete restrict,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),closed_at timestamptz);
create index nonconformities_org_status_idx on public.nonconformities(organization_id,status,due_at);create trigger nonconformities_updated before update on public.nonconformities for each row execute function public.set_updated_at();alter table public.nonconformities enable row level security;create policy "management reads nonconformities" on public.nonconformities for select to authenticated using(public.has_ticket_management_role(organization_id));
create or replace function public.create_nonconformity(target_organization_id uuid,target_type public.nonconformity_type,target_requirement text,target_description text,target_due_at timestamptz default null) returns uuid language plpgsql security definer set search_path=public as $$ declare n_id uuid;begin if not public.has_organization_role(target_organization_id,array['SUPER_ADMIN','ORG_ADMIN','MANAGER','AUDITOR']::public.platform_role[]) then raise exception 'NC_NOT_AUTHORIZED';end if;if length(trim(target_description)) not between 10 and 10000 then raise exception 'NC_INVALID_INPUT';end if;insert into public.nonconformities(organization_id,record_type,requirement_reference,description,due_at,created_by) values(target_organization_id,target_type,nullif(trim(target_requirement),''),trim(target_description),target_due_at,auth.uid()) returning id into n_id;insert into public.audit_logs(organization_id,actor_id,action,entity_type,entity_id,after_value,source) values(target_organization_id,auth.uid(),'NONCONFORMITY_CREATED','nonconformity',n_id,jsonb_build_object('type',target_type),'WEB');return n_id;end;$$;revoke all on function public.create_nonconformity(uuid,public.nonconformity_type,text,text,timestamptz) from public;grant execute on function public.create_nonconformity(uuid,public.nonconformity_type,text,text,timestamptz) to authenticated;
